  static List<FoodDbItem> search(String query) {
    if (query.isEmpty) return items;
    final q = query.toLowerCase().trim();
    return items.where((f) =>
      f.name.toLowerCase().contains(q) ||
      f.category.toLowerCase().contains(q) ||
      f.brand.toLowerCase().contains(q)
    ).toList();
  }

  static List<FoodDbItem> byCategory(String category) =>
      items.where((f) => f.category == category).toList();
}
